import {useEffect,useMemo,useRef,useState} from 'react';import Link from 'next/link';import Image from 'next/image';import {usePathname,useRouter} from 'next/navigation';import {MessageSquare,Image as ImageIcon,Video,Code2,BookOpen,Plus,ChevronDown,Sparkles,HelpCircle,Menu,Paperclip,Send,ArrowRight,Upload,Download,Search,Play,Layers3,Zap,ShieldCheck,X,Check,Copy,Square,LoaderCircle,FileText} from 'lucide-react';import {Brand} from './brand';import {SignOutButton} from './auth';import {updatePassword} from '@/app/actions/auth';
import ReactMarkdown from 'react-markdown';import remarkGfm from 'remark-gfm';import rehypeHighlight from 'rehype-highlight';
const nav=[['New Chat','/app/chat',MessageSquare],['Image Studio','/app/images',ImageIcon],['Video Studio','/app/videos',Video],['Websites','/app/websites',Code2],['Library','/app/library',BookOpen]] as const;
type AccountSummary={profile:{display_name:string;avatar_url:string|null};email:string;wallet:{balance:number;reserved:number};subscription:{plan_code:string;currency:'USD'|'INR';amount_minor:number;status:string;period_end:string|null;cancel_at_period_end:boolean}|null};
export function AppShell({children}:{children:React.ReactNode}){const path=usePathname();const [menu,setMenu]=useState(false),[account,setAccount]=useState(false),[summary,setSummary]=useState<AccountSummary|null>(null);const current=nav.find(x=>path===x[1])?.[0]||'Account';useEffect(()=>{let alive=true;const refresh=()=>fetch('/api/account/summary',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive&&data)setSummary(data)}).catch(()=>undefined);void refresh();window.addEventListener('orindle:account-updated',refresh);return()=>{alive=false;window.removeEventListener('orindle:account-updated',refresh)}},[]);const displayName=summary?.profile.display_name||summary?.email||'Account';const balance=summary?.wallet.balance??0;const reserved=summary?.wallet.reserved??0;const total=balance+reserved;const plan=summary?.subscription;return <div className="app-shell"><aside className="app-sidebar"><Brand/><Link className="sidebar-new" href="/app/chat"><Plus/>New Chat</Link><nav className="primary-nav" aria-label="Primary">{nav.map(([label,href,Icon])=><Link key={href} className={path===href?'active':''} href={href}><Icon/>{label}</Link>)}</nav>{path==='/app/chat'&&<RecentChatList/>}<div className="sidebar-bottom"><div className="plan-card"><div className="plan-card-head"><b>ORINDLE PRO</b><span>{plan?.status==='active'?'ACTIVE':'NOT ACTIVE'}</span></div><p><span>Credits remaining</span><strong>{summary?`${balance.toLocaleString()} / ${plan?'1,500':'0'}`:'Loading…'}</strong></p><div className="plan-progress"><i style={{width:plan?`${Math.min(100,Math.max(0,(total/1500)*100))}%`:'0%'}}/></div><Link href="/app/account?section=subscription">{plan?'Manage subscription':'View subscription'} <ArrowRight size={11}/></Link></div><button className="account-button" onClick={()=>setAccount(!account)} aria-expanded={account}><span className="account-avatar">{displayName.slice(0,1).toUpperCase()}</span><span><b>{displayName}</b><small>{summary?.subscription?'ORINDLE PRO':'Account'}</small></span><ChevronDown size={14}/></button>{account&&<div className="account-popover"><Link href="/app/account">Account settings</Link><Link href="/app/account?section=subscription">Billing &amp; subscription</Link><SignOutButton/></div>}</div></aside><main className="app-main"><header className="app-topbar"><button className="top-mobile-menu" onClick={()=>setMenu(!menu)} aria-label="Open navigation"><Menu size={16}/></button><div className="breadcrumbs"><span>Workspace</span><span>/</span><b>{current}</b></div><div className="topbar-right"><span className="credits-top"><Sparkles size={14}/>{summary?`${balance.toLocaleString()} credits`:'Credits unavailable'}</span><button className="help-top" aria-label="Help"><HelpCircle size={14}/></button></div></header>{menu&&<div className="mobile-menu-panel">{nav.map(([label,href,Icon])=><Link onClick={()=>setMenu(false)} href={href} key={href}><Icon/>{label}</Link>)}<Link href="/app/account">Account settings</Link><SignOutButton/></div>}{children}</main><nav className="mobile-app-nav" aria-label="Mobile workspace">{nav.map(([label,href,Icon])=><Link aria-label={label} title={label} className={path===href?'active':''} href={href} key={href}><Icon/><span>{label}</span></Link>)}</nav></div>}
function PageTitle({title,desc,action}:{title:string,desc:string,action?:React.ReactNode}){return <div className="page-title-row"><div><h1>{title}</h1><p>{desc}</p></div>{action}</div>}
function Empty({icon:Icon=Sparkles,title,desc,action}:{icon?:React.ComponentType<{size?:number}>,title:string,desc:string,action?:React.ReactNode}){return <div className="app-empty"><span className="empty-icon"><Icon size={20}/></span><h2>{title}</h2><p>{desc}</p>{action}</div>}
type CatalogModel={id:string;model_id:string;provider:string;display_name:string;description:string;context_length:number|null;input_modalities:string[];output_modalities:string[];supported_parameters:string[];metadata?:Record<string,unknown>;model_pricing?:{prompt_usd_per_token:string|number|null;completion_usd_per_token:string|number|null;image_usd?:string|number|null;video_usd_per_second?:string|number|null}|null};
type ChatMessage={id:string;role:'user'|'assistant';content:string;status?:string;error_code?:string};
type AttachedFile={id:string;name:string;type:string};
function RecentChatList(){const [items,setItems]=useState<Array<{id:string;title:string}>>([]);const path=usePathname();useEffect(()=>{let alive=true;const refresh=()=>fetch('/api/conversations?limit=8',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive&&data?.conversations)setItems(data.conversations)}).catch(()=>undefined);void refresh();window.addEventListener('orindle:conversation-updated',refresh);return()=>{alive=false;window.removeEventListener('orindle:conversation-updated',refresh)}},[path]);return <div className="recent-list"><span>Recent</span>{items.map(item=><Link key={item.id} href={`/app/chat?conversationId=${item.id}`} title={item.title}>{item.title}</Link>)}{!items.length&&<small className="recent-empty">Your recent chats will appear here.</small>}</div>}
export function ChatWorkspace({initialConversationId}:{initialConversationId?:string}){const router=useRouter();const [models,setModels]=useState<CatalogModel[]>([]);const [catalogueError,setCatalogueError]=useState('');const [provider,setProvider]=useState('All providers');const [mode,setMode]=useState('auto');const [selectedModel,setSelectedModel]=useState<CatalogModel|null>(null);const [modelMenu,setModelMenu]=useState(false);const [modelSearch,setModelSearch]=useState('');const [draft,setDraft]=useState('');const [messages,setMessages]=useState<ChatMessage[]>([]);const [conversationId,setConversationId]=useState<string|undefined>(initialConversationId);const [files,setFiles]=useState<AttachedFile[]>([]);const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const [loadingConversation,setLoadingConversation]=useState(false);const bottomRef=useRef<HTMLDivElement>(null);const inputRef=useRef<HTMLTextAreaElement>(null);const fileRef=useRef<HTMLInputElement>(null);const abortRef=useRef<AbortController|null>(null);
useEffect(()=>{let alive=true;fetch('/api/models?capability=text&limit=100',{cache:'no-store'}).then(async r=>{if(!r.ok)throw new Error('Model catalogue is not available.');return r.json()}).then(data=>{if(alive)setModels(data.models||[])}).catch(()=>{if(alive)setCatalogueError('The live model catalogue has not synchronized yet.')});return()=>{alive=false}},[]);
useEffect(()=>{let alive=true;if(!initialConversationId){setConversationId(undefined);setMessages([]);return()=>{alive=false}}setLoadingConversation(true);fetch(`/api/conversations/${initialConversationId}`,{cache:'no-store'}).then(async r=>{if(!r.ok)throw new Error('Conversation could not be loaded.');return r.json()}).then(data=>{if(!alive)return;setConversationId(data.conversation.id);setMessages(data.messages||[])}).catch(()=>{if(alive)setError('This conversation could not be loaded.')}).finally(()=>{if(alive)setLoadingConversation(false)});return()=>{alive=false}},[initialConversationId]);
useEffect(()=>{bottomRef.current?.scrollIntoView({behavior:'smooth',block:'end'})},[messages]);
const providers=useMemo(()=>['All providers',...Array.from(new Set(models.map(m=>m.provider))).sort()], [models]);const shownModels=useMemo(()=>models.filter(m=>(provider==='All providers'||m.provider===provider)&&`${m.display_name} ${m.provider} ${m.model_id}`.toLowerCase().includes(modelSearch.toLowerCase())),[models,provider,modelSearch]);
const attachFile=async(file:File)=>{setUploading(true);setError('');try{const start=await fetch('/api/files/upload-url',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,type:file.type,size:file.size,purpose:'chat'})});const started=await start.json();if(!start.ok)throw new Error(started.error||'Upload could not start.');const uploaded=await fetch(started.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!uploaded.ok)throw new Error('Private file upload failed. Check storage configuration.');const finish=await fetch('/api/files/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileId:started.fileId})});const result=await finish.json();if(!finish.ok)throw new Error(result.error||'File validation failed.');setFiles(list=>[...list,{id:started.fileId,name:file.name,type:file.type}])}catch(e){setError(e instanceof Error?e.message:'File upload failed.')}finally{setUploading(false);if(fileRef.current)fileRef.current.value=''}};
const send=async(prompt=draft,attachmentList=files)=>{const content=prompt.trim();if(!content||busy||uploading)return;setBusy(true);setError('');setDraft('');const requestId=crypto.randomUUID();const userTemp=crypto.randomUUID(),assistantTemp=crypto.randomUUID();let persistedAssistantId=assistantTemp;setMessages(old=>[...old,{id:userTemp,role:'user',content,status:'complete'},{id:assistantTemp,role:'assistant',content:'',status:'streaming'}]);const controller=new AbortController();abortRef.current=controller;try{const response=await fetch('/api/chat',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','Idempotency-Key':requestId},body:JSON.stringify({conversationId,modelId:mode==='auto'?null:selectedModel?.id,text:content,attachmentIds:attachmentList.map(f=>f.id)})});if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(errorLabel(data.error||'chat_request_failed'))}const nextConversation=response.headers.get('X-Conversation-Id')||conversationId;const assistantId=response.headers.get('X-Assistant-Message-Id')||assistantTemp;persistedAssistantId=assistantId;const userMessageId=response.headers.get('X-User-Message-Id');if(userMessageId)setMessages(old=>old.map(m=>m.id===userTemp?{...m,id:userMessageId}:m));if(nextConversation&&!conversationId){setConversationId(nextConversation);window.dispatchEvent(new Event('orindle:conversation-updated'));router.replace(`/app/chat?conversationId=${nextConversation}`,{scroll:false})}if(!response.body)throw new Error('The model returned no stream.');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='',answer='',streamError='',streamComplete=false;const appendLine=(line:string)=>{if(!line.startsWith('data:'))return;const raw=line.slice(5).trim();if(!raw)return;if(raw==='[DONE]'){streamComplete=true;return}try{const chunk=JSON.parse(raw);if(chunk.error){streamError=errorLabel(chunk.error.code||'generation_failed');return}const delta=chunk.choices?.[0]?.delta?.content;if(typeof delta==='string'){answer+=delta;setMessages(old=>old.map(m=>m.id===assistantTemp||m.id===assistantId?{...m,id:assistantId,content:answer,status:'streaming'}:m))}}catch{/* Ignore malformed provider frames; the stream status below determines success. */}};while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split(/\r?\n/);buffer=lines.pop()||'';lines.forEach(appendLine)}if(buffer)appendLine(buffer);if(streamError)throw new Error(streamError);if(!streamComplete||!answer.trim())throw new Error('The response ended before it was complete. Try again.');setMessages(old=>old.map(m=>m.id===assistantTemp||m.id===assistantId?{...m,id:assistantId,content:answer,status:'complete'}:m));setFiles([])}catch(e){if(!(e instanceof DOMException&&e.name==='AbortError'))setError(e instanceof Error?e.message:'The response failed. Try again.');setMessages(old=>old.map(m=>m.id===assistantTemp||m.id===persistedAssistantId?{...m,status:'failed'}:m))}finally{setBusy(false);abortRef.current=null;inputRef.current?.focus()}};
const startNew=()=>{abortRef.current?.abort();setConversationId(undefined);setMessages([]);setDraft('');setFiles([]);setError('');router.replace('/app/chat',{scroll:false})};return <div className="app-content"><div className="chat-workspace"><div className="chat-top-controls"><button className="app-btn" onClick={startNew}><Plus size={14}/>New chat</button><button className="model-selector" aria-expanded={modelMenu} onClick={()=>setModelMenu(!modelMenu)}><span className="provider-dot"/>{mode==='auto'?'Auto selection':selectedModel?.display_name||'Choose model'}<ChevronDown size={14}/></button>{modelMenu&&<div className="model-menu"><div className="model-menu-heading"><b>Select a chat model</b><button onClick={()=>setModelMenu(false)} aria-label="Close model selector"><X size={15}/></button></div><div className="model-menu-search"><Search size={14}/><input value={modelSearch} onChange={e=>setModelSearch(e.target.value)} placeholder="Search models" aria-label="Search chat models"/></div><div className="model-menu-filters"><select value={provider} onChange={e=>setProvider(e.target.value)} aria-label="Filter by provider">{providers.map(p=><option key={p}>{p}</option>)}</select><span>{models.length} available</span></div><button className={'model-option '+(mode==='auto'?'selected':'')} onClick={()=>{setMode('auto');setSelectedModel(null);setModelMenu(false)}}><span className="auto-model-icon"><Sparkles size={14}/></span><span><b>Auto</b><small>Choose a compatible model for each request</small></span>{mode==='auto'&&<Check size={15}/>}</button><div className="model-options-scroll">{shownModels.map(m=><button key={m.id} className={'model-option '+(mode==='manual'&&selectedModel?.id===m.id?'selected':'')} onClick={()=>{setMode('manual');setSelectedModel(m);setModelMenu(false)}}><span className="model-provider">{m.provider.slice(0,1).toUpperCase()}</span><span><b>{m.display_name}</b><small>{m.provider} · {m.context_length?`${Math.round(m.context_length/1000)}k context`:'context varies'}</small></span>{mode==='manual'&&selectedModel?.id===m.id&&<Check size={15}/>}</button>)}{!shownModels.length&&<p className="model-empty">{catalogueError||'No models match this search.'}</p>}</div></div>}</div>{messages.length===0?<div className="welcome-view"><span className="welcome-icon"><Sparkles/></span><h1>What would you like to create today?</h1><p>Start a conversation with a compatible model, or jump into a creative tool.</p></div>:<div className="chat-thread" aria-live="polite">{loadingConversation&&<p className="app-notice">Loading conversation…</p>}{messages.map((message,i)=><article className={`chat-message chat-message-${message.role}`} key={message.id}><span className="chat-message-mark">{message.role==='assistant'?<Sparkles size={15}/>:<span>D</span>}</span><div className="chat-message-body">{message.role==='assistant'?<ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeHighlight]}>{message.content||''}</ReactMarkdown>:<p>{message.content}</p>}{message.status==='streaming'&&<span className="streaming-cursor"/>}{message.status==='failed'&&<span className="failed-message">Response failed · retry your prompt</span>}{message.status==='complete'&&message.role==='assistant'&&<div className="message-actions"><button aria-label="Copy response" onClick={()=>navigator.clipboard.writeText(message.content)}><Copy size={13}/>Copy</button><button onClick={()=>{const previous=messages.slice(0,i).reverse().find(m=>m.role==='user');if(previous)send(previous.content,[])}}><ArrowRight size={13}/>Regenerate</button></div>}</div></article>)}<div ref={bottomRef}/></div>}<div className="chat-compose-area"><div className="chat-composer"><textarea ref={inputRef} aria-label="Your prompt" value={draft} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();void send()}}} placeholder="Ask anything, explore an idea, or attach a file..."/><div className="composer-actions"><button className="composer-tool" onClick={()=>fileRef.current?.click()} disabled={uploading||files.length>=5}><Paperclip/>{uploading?'Uploading…':'Attach'}</button><input ref={fileRef} type="file" className="visually-hidden" accept="image/png,image/jpeg,image/webp,image/gif,text/plain,text/csv,application/json" onChange={e=>{const selected=e.target.files?.[0];if(selected)void attachFile(selected)}}/><div className="spacer"/><span className="composer-model-current">{mode==='auto'?'Auto':selectedModel?.display_name||'Manual'}</span>{busy?<button className="composer-send stop-send" aria-label="Stop response" onClick={()=>abortRef.current?.abort()}><Square size={12}/></button>:<button className="composer-send" aria-label="Send message" onClick={()=>void send()} disabled={!draft.trim()||uploading}><Send/></button>}</div></div>{files.length>0&&<div className="attached-file-list">{files.map(file=><span key={file.id}><FileText size={13}/>{file.name}<button onClick={()=>setFiles(list=>list.filter(f=>f.id!==file.id))} aria-label={`Remove ${file.name}`}><X size={12}/></button></span>)}</div>}{error&&<p role="alert" className="chat-error">{error}</p>}<div className="quick-links"><Link href="/app/images"><ImageIcon/>Image Studio</Link><Link href="/app/videos"><Video/>Video Studio</Link><Link href="/app/websites"><Code2/>Websites</Link></div></div></div></div>}
function errorLabel(code:string){const messages:Record<string,string>={insufficient_credits:'You do not have enough credits for this request.',catalogue_unavailable:'The live model catalogue is unavailable.',no_compatible_model:'No currently available model supports the selected input.',provider_rate_limited:'The AI provider is busy. Please retry in a moment.',provider_timeout:'The model took too long to respond.',service_not_configured:'This service is not configured yet.',unauthorized:'Please sign in again.',attachment_not_validated:'An attached file is not ready yet.',attachment_format_not_supported:'This file type is not supported.',image_pricing_unavailable:'This image model has no verified output-image price.',video_pricing_unavailable:'This video model has no verified per-second price.',model_aspect_ratio_unsupported:'That aspect ratio is not supported by the selected model.',model_resolution_unsupported:'That resolution is not supported by the selected model.',model_quantity_unsupported:'That image quantity is not supported by the selected model.',model_duration_unsupported:'That duration is not supported by the selected model.',model_reference_images_unsupported:'The selected model does not support reference images.',reference_image_not_validated:'The reference image has not passed file validation.',video_completion_needs_review:'The video completed but needs usage or storage reconciliation.',credit_reconciliation_required:'Actual usage is higher than the available balance; the reservation needs review.',billing_not_configured:'Secure checkout is not configured for this environment.'};return messages[code]||'The request could not be completed. Please try again.'}
function parameterValues(model:CatalogModel|null,name:string,rangeCandidates:number[]=[]):(string|number)[]{if(!model)return [];const capabilities=model.metadata?.capabilities;if(!capabilities||typeof capabilities!=='object'||Array.isArray(capabilities))return [];const descriptor=(capabilities as Record<string,unknown>)[name];if(!descriptor||typeof descriptor!=='object')return [];const values=(descriptor as {values?:unknown}).values;if(Array.isArray(values))return values.filter((x):x is string|number=>typeof x==='string'||typeof x==='number');const range=descriptor as {min?:unknown;max?:unknown};if(typeof range.min==='number'||typeof range.max==='number')return rangeCandidates.filter(v=>(typeof range.min!=='number'||v>=range.min)&&(typeof range.max!=='number'||v<=range.max));return []}
function hasParameter(model:CatalogModel|null,name:string){return !!model&&(model.supported_parameters||[]).includes(name)||!!(model?.metadata?.capabilities&&typeof model.metadata.capabilities==='object'&&!Array.isArray(model.metadata.capabilities)&&(name in (model.metadata.capabilities as Record<string,unknown>)))}
type ImageAsset={id:string;url:string;mimeType:string;byteSize:number};type ImageJob={id:string;prompt:string;status:string;created_at:string;error_code:string|null};
export function ImageWorkspace({initialJobId}:{initialJobId?:string}){const [models,setModels]=useState<CatalogModel[]>([]);const [selectedId,setSelectedId]=useState('');const [prompt,setPrompt]=useState('');const [ratio,setRatio]=useState('');const [resolution,setResolution]=useState('');const [quantity,setQuantity]=useState(1);const [references,setReferences]=useState<AttachedFile[]>([]);const [images,setImages]=useState<ImageAsset[]>([]);const [jobs,setJobs]=useState<ImageJob[]>([]);const [jobId,setJobId]=useState('');const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const fileRef=useRef<HTMLInputElement>(null);const model=models.find(m=>m.id===selectedId)||null;const ratios=parameterValues(model,'aspect_ratio');const resolutions=parameterValues(model,'resolution');const quantityOptions=hasParameter(model,'n')?[1,...parameterValues(model,'n',[2,4]).map(Number).filter(n=>[2,4].includes(n))]:[1];const referenceSupported=!!model&&model.input_modalities.includes('image')&&hasParameter(model,'input_references');
const refreshHistory=async()=>{try{const r=await fetch('/api/images?limit=30',{cache:'no-store'});const data=await r.json();if(r.ok){setJobs(data.jobs||[]);return data.jobs as ImageJob[]}}catch{}return []};useEffect(()=>{let alive=true;fetch('/api/models?capability=image&limit=100',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive)setModels((data?.models||[]).filter((m:CatalogModel)=>m.model_pricing?.image_usd!==null&&m.model_pricing?.image_usd!==undefined))}).catch(()=>undefined);void refreshHistory().then(list=>{if(alive){const latest=list.find(j=>j.status==='completed');const target=initialJobId||latest?.id;if(target)void openImage(target,false)}});return()=>{alive=false}},[initialJobId]);
const openImage=async(id:string,showError=true)=>{try{const r=await fetch(`/api/images/${id}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||'Image job could not be loaded.');setJobId(id);setImages(data.images||[]);setPrompt(data.job?.prompt||'');setNotice(data.job?.status==='completed'?`Generation complete · ${data.images?.length||0} image(s)`:`Generation status: ${data.job?.status||'unknown'}`)}catch(e){if(showError)setError(e instanceof Error?e.message:'Image job could not be loaded.')}};
const attach=async(file:File)=>{if(!referenceSupported)return;setUploading(true);setError('');try{const start=await fetch('/api/files/upload-url',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,type:file.type,size:file.size,purpose:'image_reference'})});const info=await start.json();if(!start.ok)throw new Error(info.error||'Upload could not start.');const uploaded=await fetch(info.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!uploaded.ok)throw new Error('Reference upload failed.');const complete=await fetch('/api/files/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileId:info.fileId})});const result=await complete.json();if(!complete.ok)throw new Error(result.error||'Reference validation failed.');setReferences(list=>[...list,{id:info.fileId,name:file.name,type:file.type}])}catch(e){setError(e instanceof Error?e.message:'Reference upload failed.')}finally{setUploading(false);if(fileRef.current)fileRef.current.value=''}};
const generate=async()=>{if(!prompt.trim()||!selectedId||busy)return;setBusy(true);setError('');setNotice('Generating image…');setImages([]);try{const response=await fetch('/api/images',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({prompt,modelId:selectedId,quantity,aspectRatio:ratio||undefined,resolution:resolution||undefined,referenceFileIds:references.map(x=>x.id)})});const data=await response.json();if(!response.ok)throw new Error(errorLabel(data.error||'image_generation_failed'));setJobId(data.jobId);setImages(data.images||[]);setNotice(`Generation complete · ${data.images?.length||0} image(s) · ${data.actualCredits??0} credits charged`);setReferences([]);void refreshHistory()}catch(e){setError(e instanceof Error?e.message:'Image generation failed.');setNotice('')}finally{setBusy(false)}};
return <div className="app-content"><PageTitle title="Image Studio" desc="Create original images with live, compatible OpenRouter image models." action={<select className="select-field generation-history-select" aria-label="Image history" value={jobId} onChange={e=>{if(e.target.value)void openImage(e.target.value)}}><option value="">{jobs.length?'History':'No history'}</option>{jobs.map(j=><option key={j.id} value={j.id}>{new Date(j.created_at).toLocaleDateString()} · {j.prompt.slice(0,35)}</option>)}</select>}/><div className="tool-layout"><section className="tool-controls"><div className="field-group"><label className="field-label" htmlFor="image-model">Image model</label><select id="image-model" className="select-field" value={selectedId} onChange={e=>{setSelectedId(e.target.value);setRatio('');setResolution('');setQuantity(1)}}><option value="">Choose a priced image model</option>{models.map(m=><option key={m.id} value={m.id}>{m.display_name} · {m.provider}</option>)}</select>{!models.length&&<div className="field-help">No priced image models are synchronized yet.</div>}</div><div className="field-group"><label className="field-label" htmlFor="image-prompt">Describe your image</label><textarea id="image-prompt" className="text-field textarea-field" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Describe the subject, setting, mood, light and style…"/><div className="field-help">Be specific about composition and the details that matter.</div></div>{referenceSupported&&<div className="field-group"><span className="field-label">Reference image</span><button className="upload-box" onClick={()=>fileRef.current?.click()} disabled={uploading||references.length>=4}><Upload/>{uploading?'Uploading…':'Add a supported reference image'}</button><input ref={fileRef} className="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>{const f=e.target.files?.[0];if(f)void attach(f)}}/>{references.map(f=><div className="reference-file" key={f.id}><FileText size={12}/>{f.name}<button onClick={()=>setReferences(old=>old.filter(x=>x.id!==f.id))}><X size={12}/></button></div>)}</div>}{ratios.length>0&&<div className="field-group"><label className="field-label" htmlFor="image-ratio">Aspect ratio · supported by selected model</label><select id="image-ratio" className="select-field" value={ratio} onChange={e=>setRatio(e.target.value)}><option value="">Provider default</option>{ratios.map(x=><option key={String(x)} value={x}>{x}</option>)}</select></div>}{resolutions.length>0&&<div className="field-group"><label className="field-label" htmlFor="image-resolution">Resolution · supported by selected model</label><select id="image-resolution" className="select-field" value={resolution} onChange={e=>setResolution(e.target.value)}><option value="">Provider default</option>{resolutions.map(x=><option key={String(x)} value={x}>{x}</option>)}</select></div>}{quantityOptions.length>1&&<div className="field-group"><span className="field-label">Images · model supports n</span><div className="option-row">{quantityOptions.map(n=><button key={n} className={'option-chip '+(quantity===n?'selected':'')} onClick={()=>setQuantity(n)}>{n}</button>)}</div></div>}<button className="app-btn primary" style={{width:'100%',justifyContent:'center'}} onClick={()=>void generate()} disabled={busy||uploading||!selectedId||!prompt.trim()}>{busy?<><span className="spinner-dot"/>Generating…</>:<><Sparkles/>Generate image</>}</button>{error&&<p role="alert" className="tool-error">{error}</p>}<p className="app-notice" style={{marginTop:10}}>Model compatibility and per-image pricing are read from the synchronized catalogue. Charges use returned provider usage when available.</p></section><section className="tool-output"><div className="output-head"><b>Result</b><span>{busy?'Generating':jobId?'Saved generation':'Ready'}</span></div><div className="output-space"><div className="image-results">{images.length?images.map((image,index)=><figure key={image.id}><Image src={image.url} alt={`${prompt||'Generated image'}${images.length>1?` — ${index+1}`:''}`} width={1200} height={900} unoptimized/><figcaption><span>{image.mimeType} · {(image.byteSize/1024/1024).toFixed(1)} MB</span><button className="app-btn" onClick={()=>window.open(`/api/assets/${image.id}?redirect=1`,'_blank','noopener,noreferrer')}><Download/>Download</button></figcaption></figure>):<Empty icon={ImageIcon} title={busy?'Creating your image…':'Your image results'} desc={error?'Correct the request or choose another supported model.':'Select a compatible model and describe the image you want to create.'}/>}</div></div>{notice&&<p className="image-notice" role="status">{notice}</p>}</section></div></div>}

type VideoJob={id:string;prompt:string;status:string;created_at:string;error_code:string|null;request?:Record<string,unknown>};type VideoAsset={id:string;url:string;mime_type:string;byte_size:number};
export function VideoWorkspace({initialJobId}:{initialJobId?:string}){const [models,setModels]=useState<CatalogModel[]>([]);const [selectedId,setSelectedId]=useState('');const [prompt,setPrompt]=useState('');const [duration,setDuration]=useState('');const [ratio,setRatio]=useState('');const [resolution,setResolution]=useState('');const [reference,setReference]=useState<AttachedFile|null>(null);const [jobs,setJobs]=useState<VideoJob[]>([]);const [jobId,setJobId]=useState('');const [status,setStatus]=useState('');const [asset,setAsset]=useState<VideoAsset|null>(null);const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const fileRef=useRef<HTMLInputElement>(null);const model=models.find(m=>m.id===selectedId)||null;const durationValues=parameterValues(model,'duration',[5,8,10]);const ratios=parameterValues(model,'aspect_ratio');const resolutions=parameterValues(model,'resolution');const referenceSupported=!!model&&model.input_modalities.includes('image')&&hasParameter(model,'input_references');
const refreshHistory=async()=>{try{const r=await fetch('/api/videos?limit=30',{cache:'no-store'});const data=await r.json();if(r.ok){setJobs(data.jobs||[]);return data.jobs as VideoJob[]}}catch{}return []};useEffect(()=>{let alive=true;fetch('/api/models?capability=video&limit=100',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive)setModels((data?.models||[]).filter((m:CatalogModel)=>m.model_pricing?.video_usd_per_second!==null&&m.model_pricing?.video_usd_per_second!==undefined))}).catch(()=>undefined);void refreshHistory().then(list=>{if(!alive)return;const active=list.find(j=>['queued','submitted','processing'].includes(j.status));const latest=active||list.find(j=>j.status==='completed');const target=initialJobId||latest?.id;if(target)void openVideo(target,false)});return()=>{alive=false}},[initialJobId]);
const openVideo=async(id:string,showError=true)=>{try{const r=await fetch(`/api/videos/${id}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||'Video job could not be loaded.');setJobId(id);setStatus(data.job?.status||'');setAsset(data.video||null);setPrompt(data.job?.prompt||'');setNotice(data.job?.status==='completed'?'Video complete.':`Video status: ${data.job?.status||'unknown'}`)}catch(e){if(showError)setError(e instanceof Error?e.message:'Video job could not be loaded.')}};
useEffect(()=>{if(!jobId||!['queued','submitted','processing'].includes(status))return;let alive=true;let polls=0;const tick=async()=>{if(!alive||polls>=80)return;polls++;try{const r=await fetch(`/api/videos/${jobId}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(errorLabel(data.error||'video_status_unavailable'));if(!alive)return;setStatus(data.job?.status||'');setAsset(data.video||null);if(data.job?.status==='completed')setNotice('Video complete and saved to your Library.');if(['failed','cancelled','expired','needs_review'].includes(data.job?.status))setError(data.job.error_code==='video_completion_needs_review'?'Provider cost or file delivery needs reconciliation. Contact support before retrying.':errorLabel(data.job.error_code||data.job.status))}catch(e){if(alive)setError(e instanceof Error?e.message:'Video status could not be checked.')}};const timer=setInterval(()=>void tick(),15_000);return()=>{alive=false;clearInterval(timer)}},[jobId,status]);
const attach=async(file:File)=>{if(!referenceSupported)return;setUploading(true);setError('');try{const start=await fetch('/api/files/upload-url',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,type:file.type,size:file.size,purpose:'video_reference'})});const info=await start.json();if(!start.ok)throw new Error(info.error||'Upload could not start.');const uploaded=await fetch(info.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!uploaded.ok)throw new Error('Reference upload failed.');const complete=await fetch('/api/files/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileId:info.fileId})});const result=await complete.json();if(!complete.ok)throw new Error(result.error||'Reference validation failed.');setReference({id:info.fileId,name:file.name,type:file.type})}catch(e){setError(e instanceof Error?e.message:'Reference upload failed.')}finally{setUploading(false);if(fileRef.current)fileRef.current.value=''}};
const generate=async()=>{if(!model||!prompt.trim()||!duration||busy)return;setBusy(true);setError('');setNotice('Submitting asynchronous video generation…');setAsset(null);try{const r=await fetch('/api/videos',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({prompt,modelId:model.id,duration:Number(duration),aspectRatio:ratio||undefined,resolution:resolution||undefined,referenceFileIds:reference?[reference.id]:[]})});const data=await r.json();if(!r.ok)throw new Error(errorLabel(data.error||'video_submit_failed'));setJobId(data.jobId);setStatus(data.status||'submitted');setNotice('Video job submitted. Progress updates are polled at a bounded interval.');setReference(null);void refreshHistory()}catch(e){setError(e instanceof Error?e.message:'Video request failed.');setNotice('')}finally{setBusy(false)}};
return <div className="app-content"><PageTitle title="Video Studio" desc="Submit asynchronous video jobs and follow persisted provider status." action={<select className="select-field generation-history-select" aria-label="Video history" value={jobId} onChange={e=>{if(e.target.value)void openVideo(e.target.value)}}><option value="">{jobs.length?'History':'No history'}</option>{jobs.map(j=><option key={j.id} value={j.id}>{new Date(j.created_at).toLocaleDateString()} · {j.prompt.slice(0,34)} · {j.status}</option>)}</select>}/><div className="tool-layout"><section className="tool-controls"><div className="field-group"><label className="field-label" htmlFor="video-model">Video model</label><select id="video-model" className="select-field" value={selectedId} onChange={e=>{setSelectedId(e.target.value);setDuration('');setRatio('');setResolution('')}}><option value="">Choose a priced video model</option>{models.map(m=><option key={m.id} value={m.id}>{m.display_name} · {m.provider}</option>)}</select>{!models.length&&<div className="field-help">No priced video models are synchronized yet.</div>}</div><div className="field-group"><label className="field-label" htmlFor="video-prompt">Describe your scene</label><textarea id="video-prompt" className="text-field textarea-field" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Describe the subject, movement, camera and atmosphere…"/></div>{referenceSupported&&<div className="field-group"><span className="field-label">Reference image</span><button className="upload-box" onClick={()=>fileRef.current?.click()} disabled={uploading||!!reference}><Upload/>{uploading?'Uploading…':reference?.name||'Add supported reference image'}</button><input ref={fileRef} className="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>{const f=e.target.files?.[0];if(f)void attach(f)}}/>{reference&&<button className="remove-reference" onClick={()=>setReference(null)}><X size={12}/>Remove</button>}</div>}{durationValues.length>0&&<div className="field-group"><label className="field-label" htmlFor="video-duration">Duration · model metadata</label><select id="video-duration" className="select-field" value={duration} onChange={e=>setDuration(e.target.value)}><option value="">Choose duration</option>{durationValues.map(v=><option key={String(v)} value={v}>{v} sec</option>)}</select></div>}{ratios.length>0&&<div className="field-group"><label className="field-label" htmlFor="video-ratio">Aspect ratio · model metadata</label><select id="video-ratio" className="select-field" value={ratio} onChange={e=>setRatio(e.target.value)}><option value="">Provider default</option>{ratios.map(v=><option key={String(v)} value={v}>{v}</option>)}</select></div>}{resolutions.length>0&&<div className="field-group"><label className="field-label" htmlFor="video-resolution">Resolution · model metadata</label><select id="video-resolution" className="select-field" value={resolution} onChange={e=>setResolution(e.target.value)}><option value="">Provider default</option>{resolutions.map(v=><option key={String(v)} value={v}>{v}</option>)}</select></div>}<button className="app-btn primary" style={{width:'100%',justifyContent:'center'}} onClick={()=>void generate()} disabled={busy||uploading||!model||!duration||!prompt.trim()}>{busy?<><span className="spinner-dot"/>Submitting…</>:<><Play/>Generate video</>}</button>{error&&<p role="alert" className="tool-error">{error}</p>}<p className="app-notice" style={{marginTop:10}}>Video creation is asynchronous. Model parameters and per-second pricing come from synchronized provider metadata; actual usage is reconciled on completion.</p></section><section className="tool-output"><div className="output-head"><b>Generation</b><span className={'video-status status-'+status}>{status||'Ready'}</span></div><div className="output-space">{asset?<video className="video-result" controls preload="metadata" src={asset.url}>Video playback is not supported by this browser.</video>:<Empty icon={Video} title={status==='processing'||status==='submitted'?'Your video is being generated':status==='needs_review'?'This job needs reconciliation':'Your video workspace'} desc={status==='failed'?`Generation failed: ${errorLabel(status)}`:status==='needs_review'?'The provider completed the job but automatic cost or file reconciliation needs review.':'Choose a priced model and options supported by its live metadata.'}/>}</div>{asset&&<div style={{display:'flex',gap:8}}><button className="app-btn" onClick={()=>window.open(`/api/assets/${asset.id}?redirect=1`,'_blank','noopener,noreferrer')}><Download/>Download</button><span className="app-notice">Saved to your Library · {(asset.byte_size/1024/1024).toFixed(1)} MB</span></div>}{notice&&<p className="image-notice" role="status">{notice}</p>}</section></div></div>}
type WebsiteJob={id:string;prompt:string;status:string;created_at:string;error_code:string|null};
export function WebsiteWorkspace({initialWebsiteId}:{initialWebsiteId?:string}){const [tab,setTab]=useState('Preview');const [prompt,setPrompt]=useState('');const [html,setHtml]=useState('');const [jobId,setJobId]=useState('');const [jobs,setJobs]=useState<WebsiteJob[]>([]);const [models,setModels]=useState<CatalogModel[]>([]);const [modelId,setModelId]=useState('');const [busy,setBusy]=useState(false);const [saving,setSaving]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [loadingHistory,setLoadingHistory]=useState(true);
const reloadHistory=async()=>{try{const r=await fetch('/api/websites?limit=30',{cache:'no-store'});if(!r.ok)throw new Error();const data=await r.json();setJobs(data.websites||[]);return data.websites as WebsiteJob[]}catch{setError('Website history could not be loaded.');return []}finally{setLoadingHistory(false)}};
useEffect(()=>{let alive=true;fetch('/api/models?capability=text&limit=100',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive)setModels(data?.models||[])}).catch(()=>undefined);void reloadHistory().then(items=>{if(!alive)return;const latest=items?.find(j=>j.status==='completed');const target=initialWebsiteId||latest?.id;if(target)void openWebsite(target,false)});return()=>{alive=false}},[initialWebsiteId]);
async function openWebsite(id:string,showError=true){try{const r=await fetch(`/api/websites/${id}`,{cache:'no-store'});const data=await r.json();if(!r.ok)throw new Error(data.error||'Website could not be loaded.');setJobId(id);setHtml(data.html||'');setPrompt(data.website?.prompt||'');setNotice(data.html?'Website loaded.':'This generation is still running.')}catch(e){if(showError)setError(e instanceof Error?e.message:'Website could not be loaded.')}}
const generate=async()=>{if(prompt.trim().length<8||busy)return;setBusy(true);setError('');setNotice('Generating standalone HTML…');try{const r=await fetch('/api/websites',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({prompt,modelId:modelId||null})});const data=await r.json();if(!r.ok)throw new Error(errorLabel(data.error||'website_generation_failed'));setHtml(data.html||'');setJobId(data.jobId);setNotice('Website generated and saved to your Library.');setTab('Preview');const items=await reloadHistory();if(!items.some(j=>j.id===data.jobId))setJobs(old=>[{id:data.jobId,prompt,status:'completed',created_at:new Date().toISOString(),error_code:null},...old])}catch(e){setError(e instanceof Error?e.message:'Website generation failed.');setNotice('')}finally{setBusy(false)}};
const save=async()=>{if(!jobId||!html)return;setSaving(true);setError('');try{const r=await fetch(`/api/websites/${jobId}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({html})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Website could not be saved.');setNotice('Your HTML changes are saved.')}catch(e){setError(e instanceof Error?e.message:'Website could not be saved.')}finally{setSaving(false)}};
const download=()=>{if(jobId)window.open(`/api/websites/${jobId}/download?redirect=1`,'_blank','noopener,noreferrer')};
const previewDoc=useMemo(()=>{if(!html)return '';const policy=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data: blob:; style-src 'unsafe-inline' data:; script-src 'unsafe-inline'; font-src data:; media-src data: blob:; connect-src 'none'; form-action 'none'; base-uri 'none'">`;return /<head\b[^>]*>/i.test(html)?html.replace(/<head\b[^>]*>/i,m=>m+policy):html.replace(/<html\b[^>]*>/i,m=>m+'<head>'+policy+'</head>')},[html]);const done=jobs.filter(j=>j.status==='completed');
return <div className="app-content"><PageTitle title="Website Builder" desc="Generate, edit and download a standalone HTML website. Preview runs in a sandbox." action={<><button className="app-btn" onClick={()=>void save()} disabled={!jobId||!html||saving}>{saving?'Saving…':'Save changes'}</button><button className="app-btn" onClick={()=>void download()} disabled={!jobId||!html}><Download/>Download HTML</button></>}/><section className="website-prompt-panel"><div className="field-group"><label className="field-label" htmlFor="site-prompt">What should your website be about?</label><textarea id="site-prompt" className="text-field website-prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} placeholder="Describe the purpose, audience, sections and visual direction…"/><div className="website-generate-row"><label className="website-model-choice">Text model<select className="select-field" value={modelId} onChange={e=>setModelId(e.target.value)}><option value="">Auto selection</option>{models.map(m=><option value={m.id} key={m.id}>{m.display_name}</option>)}</select></label><span className="field-help">One self-contained HTML file · no hosting or full-stack generation</span><button className="app-btn primary" onClick={()=>void generate()} disabled={busy||prompt.trim().length<8}>{busy?<><span className="spinner-dot"/>Generating…</>:<><Sparkles/>Generate website</>}</button></div>{(error||notice)&&<p className={error?'website-error':'website-notice'} role={error?'alert':'status'}>{error||notice}</p>}</div></section><div className="website-workspace"><div className="web-editor-toolbar"><b>{jobId?(done.find(j=>j.id===jobId)?.prompt||prompt).slice(0,58)||'Generated website':'Untitled website'} <small>· {html?'Saved website':'No generated file'}</small></b><div className="website-toolbar-right"><select aria-label="Website history" value={jobId} onChange={e=>{if(e.target.value)void openWebsite(e.target.value)}}><option value="">{loadingHistory?'Loading history…':done.length?'Recent websites':'No saved websites'}</option>{done.map(j=><option value={j.id} key={j.id}>{new Date(j.created_at).toLocaleDateString()} · {j.prompt.slice(0,48)}</option>)}</select>{['Code Editor','Preview'].map(x=><button onClick={()=>setTab(x)} className={tab===x?'selected':''} key={x}>{x}</button>)}</div></div><div className="web-work-area">{tab==='Code Editor'?<textarea className="html-code-editor" aria-label="Standalone HTML code" value={html} onChange={e=>setHtml(e.target.value)} placeholder="Generated standalone HTML will appear here. Describe your website and select Generate website." spellCheck={false}/>:html?<iframe className="website-sandbox" title="Standalone website preview" sandbox="allow-scripts" referrerPolicy="no-referrer" srcDoc={previewDoc}/>:<Empty icon={Code2} title="Your website workspace" desc="Describe a site above. The result will be generated as one standalone HTML file."/>}</div></div><p className="app-notice" style={{marginTop:10}}>Preview isolation is enabled. External network resources and navigation are blocked in the sandbox.</p></div>}
type LibraryRecord={id:string;category:'image'|'video'|'website'|'chat'|'file';title:string;createdAt:string;metadata:Record<string,unknown>;conversationId:string|null;assetId:string|null;fileId:string|null;source:'library'|'upload'};
export function LibraryWorkspace(){const router=useRouter();const [filter,setFilter]=useState('all');const [search,setSearch]=useState('');const [items,setItems]=useState<LibraryRecord[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [opening,setOpening]=useState('');const filters=[['all','All'],['image','Images'],['video','Videos'],['website','Websites'],['chat','Chats'],['file','Files']];useEffect(()=>{const controller=new AbortController();const timer=setTimeout(()=>{setLoading(true);fetch(`/api/library?type=${filter}&q=${encodeURIComponent(search)}`,{cache:'no-store',signal:controller.signal}).then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error||'Library could not be loaded.');setItems(data.items||[]);setError('')}).catch(e=>{if(e.name!=='AbortError')setError('Your Library is temporarily unavailable.')}).finally(()=>setLoading(false))},200);return()=>{clearTimeout(timer);controller.abort()}},[filter,search]);async function openItem(item:LibraryRecord){setOpening(item.id);setError('');try{if(item.category==='chat'&&item.conversationId){router.push(`/app/chat?conversationId=${item.conversationId}`);return}if(item.category==='website'&&item.metadata.job_id){router.push(`/app/websites?websiteId=${item.metadata.job_id}`);return}if(item.category==='image'&&item.metadata.job_id){router.push(`/app/images?jobId=${item.metadata.job_id}`);return}if(item.category==='video'&&item.metadata.job_id){router.push(`/app/videos?jobId=${item.metadata.job_id}`);return}if(item.category==='file'&&item.fileId){window.open(`/api/files/${item.fileId}/download?redirect=1`,'_blank','noopener,noreferrer');return}setError('This item cannot be opened yet.')}catch(e){setError(e instanceof Error?e.message:'This item could not be opened.')}finally{setOpening('')}}async function removeItem(item:LibraryRecord){if(!confirm(`Remove “${item.title}” from your Library?`))return;try{const source=item.source==='upload'?'?source=upload':'';const r=await fetch(`/api/library/${item.id}${source}`,{method:'DELETE'});if(!r.ok)throw new Error();setItems(old=>old.filter(x=>x.id!==item.id))}catch{setError('This item could not be removed.')}}return <div className="app-content"><PageTitle title="Library" desc="Your saved chats, files and generated work, together in one place."/><div className="library-tools"><label className="library-search"><Search size={14}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search your library" aria-label="Search library"/></label><div className="library-filters">{filters.map(([key,label])=><button key={key} onClick={()=>setFilter(key)} className={filter===key?'active':''}>{label}</button>)}</div></div>{error&&<p className="chat-error" role="alert">{error}</p>}{loading?<div className="app-empty"><span className="empty-icon"><LoaderCircle size={20}/></span><h2>Loading your Library</h2></div>:items.length===0?<Empty icon={BookOpen} title="Your Library is ready" desc="Generated websites, chats and uploaded files you keep will appear here."/>:<div className="library-grid">{items.map(item=><article className="library-item" key={`${item.source}-${item.id}`}><div className={'library-thumb thumb-'+item.category}><span className="library-category-icon">{item.category==='image'?<ImageIcon/>:item.category==='video'?<Video/>:item.category==='website'?<Code2/>:item.category==='chat'?<MessageSquare/>:<FileText/>}</span><span>{item.category.toUpperCase()}</span></div><div className="library-item-meta"><div><small>{item.category.toUpperCase()}</small><b title={item.title}>{item.title}</b><span>{new Date(item.createdAt).toLocaleDateString()} · {item.source==='upload'?String(item.metadata.mime_type||'File'):item.category==='website'?'Standalone HTML':'Saved item'}</span></div><div className="library-item-actions"><button onClick={()=>void openItem(item)} disabled={opening===item.id} aria-label={'Open '+item.title}><ArrowRight size={14}/></button><button onClick={()=>void removeItem(item)} aria-label={'Remove '+item.title}><X size={14}/></button></div></div></article>)}</div>}</div>}
export function ModelsWorkspace(){const tasks=['Writing and editing','Reasoning','Coding','Research','Summarization','Translation','Image creation','Video creation','File analysis','HTML generation','Creative exploration','Long-form context'];return <div className="app-content"><PageTitle title="Model catalogue" desc="Explore task categories while the synchronized live model catalogue is being connected." action={<button className="app-btn"><Search/>Search catalogue</button>}/><div className="app-notice" style={{marginBottom:16}}>No current model names or count are asserted here. Live catalogue synchronization is required before listing available models or claiming 100+ unique chat-capable options.</div><div className="models-page-grid">{tasks.map((name,i)=><article className="catalogue-card" key={name}><span className={'model-provider mp-'+(i%5)}>{String(i+1).padStart(2,'0')}</span><div><h3>{name}</h3><p>Task category · available model support depends on the synchronized catalogue.</p></div></article>)}</div></div>}
type AccountUsageRow={id:string;kind?:string;amount?:number;balance_after?:number;provider_cost_usd?:number;description?:string;created_at?:string;currency?:string;amount_minor?:number;status?:string;occurred_at?:string};
export function AccountWorkspace({initialSection='Profile',checkoutState=''}:{initialSection?:string;checkoutState?:string}){const [tab,setTab]=useState(['Profile','Subscription','Credit usage','Billing history','Security'].includes(initialSection)?initialSection:'Profile');const [summary,setSummary]=useState<AccountSummary|null>(null);const [quote,setQuote]=useState<{currency:'USD'|'INR';amountMinor:number;formattedPrice:string;creditsPerPeriod:number;available:boolean}|null>(null);const [name,setName]=useState('');const [rows,setRows]=useState<AccountUsageRow[]>([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState(checkoutState==='return'?'Checkout returned. Subscription access and credits update only after a verified Dodo webhook.':checkoutState==='cancelled'?'Checkout was cancelled; no subscription has been activated.':checkoutState==='password_updated'?'Password updated.':'');const router=useRouter();const tabs=['Profile','Subscription','Credit usage','Billing history','Security'];useEffect(()=>{let alive=true;Promise.all([fetch('/api/account/summary',{cache:'no-store'}).then(r=>r.ok?r.json():null),fetch('/api/billing/quote',{cache:'no-store'}).then(r=>r.ok?r.json():null)]).then(([account,price])=>{if(!alive)return;if(account){setSummary(account);setName(account.profile?.display_name||'')}if(price)setQuote(price)}).catch(()=>{if(alive)setError('Account information could not be loaded.')}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[]);useEffect(()=>{if(tab!=='Credit usage'&&tab!=='Billing history')return;let alive=true;const kind=tab==='Credit usage'?'credits':'billing';fetch(`/api/account/usage?kind=${kind}`,{cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(alive)setRows(kind==='credits'?(data?.transactions||[]):(data?.payments||[]))}).catch(()=>{if(alive)setError('History is temporarily unavailable.')});return()=>{alive=false}},[tab]);
const saveProfile=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/account/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({displayName:name})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Profile could not be saved.');setSummary(old=>old?{...old,profile:data.profile}:old);setNotice('Profile updated.');window.dispatchEvent(new Event('orindle:account-updated'))}catch(err){setError(err instanceof Error?err.message:'Profile could not be saved.')}finally{setBusy(false)}};
const startCheckout=async()=>{setBusy(true);setError('');try{const r=await fetch('/api/billing/checkout',{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});const data=await r.json();if(!r.ok)throw new Error(billingError(data.error||'checkout_failed'));window.location.assign(data.checkoutUrl)}catch(err){setError(err instanceof Error?err.message:'Checkout could not be started.')}finally{setBusy(false)}};
const cancelSubscription=async()=>{if(!confirm('Schedule ORINDLE PRO cancellation at the end of the current billing period?'))return;setBusy(true);setError('');try{const r=await fetch('/api/billing/cancel',{method:'POST'});const data=await r.json();if(!r.ok)throw new Error(billingError(data.error||'cancel_failed'));setNotice('Cancellation is scheduled for the end of your current billing period.');setSummary(old=>old?.subscription?{...old,subscription:{...old.subscription,cancel_at_period_end:true}}:old)}catch(err){setError(err instanceof Error?err.message:'Cancellation could not be scheduled.')}finally{setBusy(false)}};
const amount=(currency:string,minor:number)=>new Intl.NumberFormat(currency==='INR'?'en-IN':'en-US',{style:'currency',currency,maximumFractionDigits:currency==='INR'?0:2}).format(minor/(currency==='INR'?100:100));return <div className="app-content"><PageTitle title="Account settings" desc="Manage your profile, subscription, credit usage and account security."/><div className="account-tabs">{tabs.map(x=><button onClick={()=>{setTab(x);setError('');setNotice('');router.replace(`/app/account?section=${encodeURIComponent(x.toLowerCase().replace(' ','-'))}`,{scroll:false})}} className={tab===x?'selected':''} key={x}>{x}</button>)}</div>{(error||notice)&&<p className={error?'account-error':'account-notice'} role={error?'alert':'status'}>{error||notice}</p>}{loading?<section className="page-card account-loading"><LoaderCircle size={18}/>Loading account…</section>:tab==='Profile'?<div className="settings-grid"><form className="page-card" onSubmit={saveProfile}><h2>Profile information</h2><div className="field-group"><label className="field-label" htmlFor="profile-name">Display name</label><input id="profile-name" className="text-field" value={name} onChange={e=>setName(e.target.value)} maxLength={80} required/></div><div className="field-group"><label className="field-label" htmlFor="profile-email">Email address</label><input id="profile-email" className="text-field" value={summary?.email||''} readOnly/><div className="field-help">Email changes require a verified Supabase email-change flow.</div></div><button className="app-btn primary" disabled={busy}>{busy?'Saving…':'Save changes'}</button></form><section className="page-card"><h2>Account</h2><div className="setting-row"><span><b>Authentication</b><small>{summary?.email||'Signed-in account'}</small></span><span className="account-status-pill">Verified session</span></div><div className="setting-row"><span><b>Workspace appearance</b><small>Orindle uses a calm light appearance.</small></span><span className="account-status-pill">Light</span></div></section></div>:tab==='Subscription'?<section className="page-card account-subscription-card"><h2>ORINDLE PRO</h2>{summary?.subscription?<><div className="subscription-status"><span className={'subscription-state state-'+summary.subscription.status}>{summary.subscription.status.replace('_',' ')}</span><span>{summary.subscription.currency} fixed checkout price</span></div><div className="billing-price">{amount(summary.subscription.currency,summary.subscription.amount_minor)} <small>/ month</small></div><p className="account-muted">1,500 credits per successful monthly billing period.</p>{summary.subscription.period_end&&<div className="setting-row"><span><b>{summary.subscription.cancel_at_period_end?'Access through':'Next billing date'}</b><small>{new Date(summary.subscription.period_end).toLocaleDateString()}</small></span></div>}{summary.subscription.cancel_at_period_end?<p className="account-notice">Cancellation is scheduled. Existing benefits continue through the current billing period.</p>:summary.subscription.status==='active'&&<button className="app-btn" onClick={()=>void cancelSubscription()} disabled={busy}>{busy?'Updating…':'Cancel at period end'}</button>}</>:<><div className="billing-price">{quote?.formattedPrice||'$14.99'} <small>/ month</small></div><p className="account-muted">{quote?.currency==='INR'?'India checkout · fixed INR price':'USD checkout · international/default price'} · 1,500 credits per successful monthly billing period.</p><button className="app-btn primary" onClick={()=>void startCheckout()} disabled={busy||!quote?.available}>{busy?'Starting secure checkout…':'Continue to secure checkout'}</button>{!quote?.available&&<p className="app-notice">Checkout is not configured for this environment. No payment has been created.</p>}</>}</section>:tab==='Credit usage'?<section className="page-card account-history-card"><div className="account-history-summary"><div><small>AVAILABLE CREDITS</small><b>{(summary?.wallet.balance??0).toLocaleString()}</b></div><div><small>RESERVED</small><b>{(summary?.wallet.reserved??0).toLocaleString()}</b></div><div><small>PLAN</small><b>{summary?.subscription?.status==='active'?'ORINDLE PRO':'No active plan'}</b></div></div><h2>Credit transactions</h2>{rows.length?<div className="account-history-list">{rows.map(row=><article key={row.id}><span><b>{row.description||row.kind}</b><small>{row.created_at?new Date(row.created_at).toLocaleString():''}{row.provider_cost_usd!==undefined?` · Provider cost $${Number(row.provider_cost_usd).toFixed(6)}`:''}</small></span><strong className={(row.amount||0)<0?'amount-negative':'amount-positive'}>{(row.amount||0)>0?'+':''}{(row.amount||0).toLocaleString()}</strong></article>)}</div>:<p className="account-muted">No credit transactions are recorded for this account yet.</p>}</section>:tab==='Billing history'?<section className="page-card account-history-card"><h2>Billing history</h2>{rows.length?<div className="account-history-list">{rows.map(row=><article key={row.id}><span><b>{row.currency?amount(row.currency,row.amount_minor||0):'Payment'} · {row.status}</b><small>{row.occurred_at?new Date(row.occurred_at).toLocaleString():''} · Dodo Payments</small></span><strong>{row.status}</strong></article>)}</div>:<p className="account-muted">No successful payments have been recorded.</p>}</section>:<div className="settings-grid"><section className="page-card"><h2>Change password</h2><p className="account-muted">Use a unique password with at least 12 characters.</p><form action={updatePassword} className="security-password-form"><div className="field-group"><label className="field-label" htmlFor="new-password">New password</label><input id="new-password" name="password" type="password" minLength={12} maxLength={128} autoComplete="new-password" className="text-field" required/></div><div className="field-group"><label className="field-label" htmlFor="password-confirmation">Confirm password</label><input id="password-confirmation" name="password_confirmation" type="password" minLength={12} maxLength={128} autoComplete="new-password" className="text-field" required/></div><button className="app-btn primary">Update password</button></form></section><section className="page-card"><h2>Sign out</h2><p className="account-muted">Sign out from your Orindle session on this device.</p><SignOutButton/></section></div>}</div>}
function billingError(code:string){const errors:Record<string,string>={billing_not_configured:'Secure checkout is not configured for this environment.',live_billing_requires_explicit_approval:'Live billing is disabled until explicitly approved.',subscription_already_active:'An active ORINDLE PRO subscription already exists.',checkout_already_pending:'A checkout session is already pending; finish or cancel it before starting another.',insufficient_credits:'Not enough credits for this request.'};return errors[code]||'The billing request could not be completed.'}
export function AdminWorkspace(){return <main className="admin-shell"><aside className="admin-sidebar"><Brand/><span className="admin-side-label">OPERATIONS</span><button className="active"><Layers3 size={16}/>Overview</button><button><Sparkles size={16}/>Model catalogue</button><button><Zap size={16}/>Integrations</button><button><ShieldCheck size={16}/>Security</button><div className="admin-sidebar-foot">Restricted area<br/>Authorization not enabled</div></aside><section className="admin-main"><header className="admin-top"><span>Orindle <i>/</i> Operations</span><span className="admin-demo-badge">FOUNDATION PREVIEW</span></header><div className="admin-content"><div className="page-title-row"><div><h1>Operations overview</h1><p>Platform status foundations. No administrative or customer data is connected.</p></div><button className="app-btn">Last updated · Demo</button></div><div className="admin-warning"><ShieldCheck size={16}/><span><b>Protected access is not implemented.</b> This route must be restricted with server-side role authorization before deployment.</span></div><div className="admin-stat-grid"><article><small>MODEL CATALOGUE</small><b>Not connected</b><span>Sync status</span></article><article><small>PAYMENTS</small><b>Not connected</b><span>Dodo configuration</span></article><article><small>DATABASE</small><b>Not connected</b><span>Persistence layer</span></article><article><small>AUTHENTICATION</small><b>Not connected</b><span>Identity provider</span></article></div><section className="page-card admin-table-card"><div className="admin-table-head"><div><h2>System integrations</h2><p>Illustrative status rows · no live service checks</p></div><button className="app-btn">Export</button></div><div className="admin-table"><div className="admin-table-row admin-table-label"><span>INTEGRATION</span><span>STATUS</span><span>LAST CHECK</span></div>{[['Model catalogue','Not configured'],['Payment processing','Not configured'],['Private file storage','Not configured'],['Email delivery','Not configured']].map(([name,status])=><div className="admin-table-row" key={name}><span>{name}</span><span><i className="admin-status-dot"/>{status}</span><span>—</span></div>)}</div></section></div></section></main>}
export function DemoMobileMenuStyle(){return null}
